import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const MAX_SIZE = 200;
const DEFAULT_SIZE = 20;
const MONTH_PATTERN = /^[0-9]{4}(0[1-9]|1[0-2])$/;

@Controller('api/v1')
export class FnSfr02002Controller {
  @Post('/withholding-adjustments')
  @HttpCode(200)
  async createWithholdingAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const reason = data['reason'];
    const content = data['content'];
    const startMonth = data['startMonth'];
    if (typeof reason !== 'string' || reason.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 사유를 입력해 주세요.');
    }
    if (typeof content !== 'string' || content.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 내용을 입력해 주세요.');
    }
    if (typeof startMonth !== 'string' || !MONTH_PATTERN.test(startMonth)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작월은 YYYYMM 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO withholding_adjustment
          (employee_id, reason, content, start_month, status, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), :reason, :content, :startMonth, '신청', now(), now())
         RETURNING withholding_adjustment_id AS "withholdingAdjustmentId"`,
        { userId: user.id, reason, content, startMonth },
      );
      return rows[0];
    });
  }

  @Get('/withholding-adjustments')
  async listWithholdingAdjustments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '급여 담당자');
    let isPayroll = true;
    try {
      user.require('급여 담당자');
    } catch (e) {
      isPayroll = false;
    }
    const q = checks.queryOf(req.query);
    const pageRaw = q['page'] === undefined || q['page'] === '' ? '0' : String(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? String(DEFAULT_SIZE) : String(q['size']);
    if (!/^[0-9]+$/.test(pageRaw) || !/^[0-9]+$/.test(sizeRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 숫자로 입력해 주세요.');
    }
    const page = Number(pageRaw);
    const size = Math.min(Math.max(Number(sizeRaw), 1), MAX_SIZE);
    const status = q['status'] === undefined || q['status'] === '' ? null : String(q['status']);
    const startMonth = q['startMonth'] === undefined || q['startMonth'] === '' ? null : String(q['startMonth']);
    if (status !== null && status !== '신청' && status !== '승인') {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 상태는 신청 또는 승인이어야 합니다.');
    }
    if (startMonth !== null && !MONTH_PATTERN.test(startMonth)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작월은 YYYYMM 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const params = {
        userId: user.id,
        all: isPayroll,
        status,
        startMonth,
        limit: size,
        offset: page * size,
      };
      const where = `(CAST(:all AS boolean) OR employee_id = CAST(:userId AS bigint))
          AND (CAST(:status AS text) IS NULL OR status = CAST(:status AS text))
          AND (CAST(:startMonth AS text) IS NULL OR start_month = CAST(:startMonth AS text))`;
      const items = await db.query(
        `SELECT withholding_adjustment_id AS "withholdingAdjustmentId",
                employee_id AS "employeeId",
                reason AS "reason",
                content AS "content",
                start_month AS "startMonth",
                status AS "status"
           FROM withholding_adjustment
          WHERE ${where}
          ORDER BY withholding_adjustment_id DESC
          LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM withholding_adjustment WHERE ${where}`,
        { userId: user.id, all: isPayroll, status, startMonth },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/withholding-adjustments/:withholdingAdjustmentId/approve')
  @HttpCode(200)
  async approveWithholdingAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = req.params['withholdingAdjustmentId'];
    if (typeof id !== 'string' || !/^[0-9]+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 신청 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status", CAST(employee_id AS text) AS "employeeId"
           FROM withholding_adjustment
          WHERE withholding_adjustment_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'WITHHOLDING_ADJUSTMENT_NOT_FOUND', '조정 신청을 찾을 수 없습니다.');
      }
      if (rows[0].status !== '신청') {
        throw new ApiError(409, 'WITHHOLDING_ADJUSTMENT_ALREADY_APPROVED', '이미 승인된 신청입니다.');
      }
      if (String(rows[0].employeeId) === String(user.id)) {
        throw new ApiError(403, 'FORBIDDEN', '본인의 신청은 승인할 수 없습니다.');
      }
      await db.execute(
        `UPDATE withholding_adjustment
            SET status = '승인',
                approver_id = CAST(:userId AS bigint),
                approved_at = now(),
                updated_at = now()
          WHERE withholding_adjustment_id = CAST(:id AS bigint)`,
        { id, userId: user.id },
      );
      return { status: '승인' };
    });
  }
}

