import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Tiles,
  Form, Field, TextInput, Select, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr02002Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [status, setStatus] = useState('');
  const [startMonth, setStartMonth] = useState('');
  const [applied, setApplied] = useState({ status: '', startMonth: '' });
  const [creating, setCreating] = useState(false);
  const [approving, setApproving] = useState<Row | null>(null);
  const [reason, setReason] = useState('');
  const [content, setContent] = useState('');
  const [newMonth, setNewMonth] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/withholding-adjustments', role, undefined, {
      status: applied.status,
      startMonth: applied.startMonth,
      page,
      size: SIZE,
    }),
    [role, page, applied.status, applied.startMonth],
  );

  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;
  const waiting = rows.filter((r) => r.status === '신청').length;
  const isPayroll = role === '급여 담당자';

  function search() {
    setPage(0);
    setApplied({ status, startMonth });
  }

  function reset() {
    setStatus('');
    setStartMonth('');
    setPage(0);
    setApplied({ status: '', startMonth: '' });
  }

  function openCreate() {
    setReason('');
    setContent('');
    setNewMonth('');
    setCreating(true);
  }

  async function submitCreate() {
    if (reason.trim() === '' || content.trim() === '' || newMonth.trim() === '') {
      throw new Error('조정 사유, 조정 내용, 적용 시작월을 모두 입력해 주세요.');
    }
    await call('POST', '/withholding-adjustments', role, {
      reason,
      content,
      startMonth: newMonth,
    });
    notify('조정 신청을 등록했습니다.');
    setCreating(false);
    list.reload();
  }

  async function submitApprove() {
    if (!approving) return;
    await call('POST', `/withholding-adjustments/${String(approving.withholdingAdjustmentId)}/approve`, role, {});
    notify('승인했습니다.');
    setApproving(null);
    list.reload();
  }

  const columns = [
    { key: 'withholdingAdjustmentId', label: '신청 ID' },
    {
      key: 'employeeId',
      label: '신청자',
      render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} />,
    },
    { key: 'reason', label: '조정 사유' },
    { key: 'content', label: '조정 내용' },
    { key: 'startMonth', label: '적용 시작월' },
    { key: 'status', label: '처리 상태', render: (r: Row) => <Badge value={r.status} /> },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) => (isPayroll && r.status === '신청' ? (
        <button type="button" onClick={(e) => { e.stopPropagation(); setApproving(r); }}>
          승인
        </button>
      ) : null),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles items={[['조회 건수', total], ['승인 대기 (현재 쪽)', waiting]]} />
      </section>
      <section className="box span-12">
        <h2>조정 신청</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="처리 상태">
            <Select value={status} onChange={setStatus} options={[['신청', '신청'], ['승인', '승인']]} placeholder="전체" />
          </Field>
          <Field label="적용 시작월">
            <TextInput value={startMonth} onChange={setStartMonth} placeholder="YYYYMM" />
          </Field>
        </Filters>
        <Band total={total}>
          {role === '임직원' ? (
            <button type="button" onClick={openCreate}>조정 신청</button>
          ) : null}
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={rows} empty="조정 신청이 없습니다." />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="조정 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="신청">
            <Field label="조정 사유" required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            <Field label="조정 내용" required wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="적용 시작월" required hint="YYYYMM 형식">
              <TextInput value={newMonth} onChange={setNewMonth} placeholder="202501" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {approving ? (
        <Drawer title="조정 신청 승인" onClose={() => setApproving(null)}>
          <Form onSubmit={submitApprove} submit="승인" note={<span>이 조정 신청을 승인합니다.</span>}>
            <Field label="조정 사유" wide>
              <span>{String(approving.reason ?? '')}</span>
            </Field>
            <Field label="조정 내용" wide>
              <span>{String(approving.content ?? '')}</span>
            </Field>
            <Field label="적용 시작월">
              <span>{String(approving.startMonth ?? '')}</span>
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
